import os

def common_prefix_path(paths):
    if not paths:
        return ""

    # Normalize all paths to handle different separators and trailing slashes consistently
    # os.path.normpath handles this, but we need to ensure POSIX semantics for comparison
    # We will use os.path.sep for splitting, but treat '/' as the universal separator for comparison logic

    # Convert all paths to use forward slashes for consistent splitting, as per POSIX semantics
    normalized_paths = [path.replace(os.sep, '/') for path in paths]

    if not normalized_paths:
        return ""

    # Split each path into components
    path_components = [p.split('/') for p in normalized_paths]

    # If there's only one path, it is its own prefix (though usually we expect multiple)
    if len(path_components) == 1:
        return normalized_paths[0]

    # Find the common prefix among all component lists
    prefix_length = 0
    for i in range(len(path_components[0])):
        component = path_components[0][i]
        is_common = True
        for other_components in path_components[1:]:
            if i >= len(other_components) or other_components[i] != component:
                is_common = False
                break

        if is_common:
            prefix_length += 1
        else:
            break

    # Reconstruct the path from the common components
    common_parts = path_components[0][:prefix_length]

    # Join them back using POSIX separator '/'
    return "/".join(common_parts)

import os

def normalize_segments(path):
    """
    Normalizes a POSIX-style path by removing '.' and '..' segments,
    and collapsing multiple slashes, without allowing the result to escape above root for relative paths.
    """
    if not path:
        return ""

    # Split the path by '/'
    segments = path.split('/')
    new_segments = []

    for segment in segments:
        if segment == '' or segment == '.':
            # Ignore empty segments (from // or leading/trailing /) and '.'
            continue
        elif segment == '..':
            # Handle '..'
            if new_segments:
                # If there are segments, pop the last one (unless it's the root context)
                new_segments.pop()
            # If new_segments is empty, '..' at the root level is ignored (cannot go above root)
        else:
            # Regular segment
            new_segments.append(segment)

    # Reconstruct the path
    # If the original path started with '/', the result should start with '/'
    if path.startswith('/'):
        return '/' + '/'.join(new_segments)
    else:
        return '/'.join(new_segments)
